    log(chalk.cyan('Deleting dir: lib'))
    fs.rmSync(targetDir, { recursive: true })
  }
  log(chalk.cyanBright('Building...'))
  const bundle = await rollup.rollup({
    input: path.resolve(__dirname, '../src/index.ts'),
    plugins: [
      typescript({
        clean: true,
      }),
      strip({
        include: ['**/*.(js|ts|mjs)'],
        functions: ['console.*'],
      }),
    ],
    external: source => {
      return /^zrender/g.test(source)
    },
  })
  bundle.write({
    format: 'esm',
    file: path.resolve(__dirname, '../lib/index.mjs'),
    name: 'jl-engine',
    sourcemap: true,
  })
  log(chalk.greenBright('Build success!'))
