const path = require('path')
const fs = require('fs')
const inquirer = require('inquirer')
    // ...
const versionRegExp = /(\d+\.\d+\.\d+)/g
const indexPath = path.resolve(__dirname, '../src/index.ts')
const packageJsonPath = path.resolve(__dirname, '../package.json')
    // ...
const package = require(packageJsonPath)
let content = fs.readFileSync(indexPath, 'utf-8')
    // ...
function updateVersionNo(version) {
  content = content.replace(versionRegExp, version)
  fs.writeFileSync(indexPath, content, err => {
    console.error(err)
  })
  package.version = version
  package.main = 'lib'
  fs.writeFileSync(packageJsonPath, JSON.stringify(package, null, 2), err =>
    console.error(err)
  )
}
    // ...
async function prePublish() {
  const versionStr = versionRegExp.exec(content)[0]
  console.log(chalk.yellow(`Fetching Remote Version...`))
  const removeVersion = await getRemoteVersion()
  console.log(chalk.yellowBright(`Remote Version: ${removeVersion}`))
  const verChoice = await inquirer.prompt([
    {
      type: 'list',
      name: 'ver',
      message: `Please select version number to publish.`,
      choices: ['major', 'minor', 'patch'].map((str, idx) => {
        const verNo = increaseVerNo(versionStr, idx)
        return {
          name: `${str}: ${verNo}`,
          value: verNo,
        }
      }),
    },
  ])
  const res = await inquirer.prompt([
    {
      type: 'confirm',
      name: 'continue',
      message: `Are you sure to publish version ${verChoice.ver}?`,
    },
  ])
  if (res.continue) {
    updateVersionNo(verChoice.ver)
  } else {
    process.exit(1)
  }
}
    // ...
prePublish()

