exports.getRemoteVersion = function () {
  return new Promise((resolve, reject) => {
    let data = ''
    const req = https.get('https://registry.npmjs.org/jl-engine/', res => {
      res.on('data', chunk => {
        data += chunk
      })
      res.on('end', () => {
        data = JSON.parse(data)
        resolve(data['dist-tags'].latest)
      })
    })
    req.on('error', err => {
      console.log(err)
      reject()
    })

    req.end()
  })
}
